_value_satisfying(op: str, rhs: Any) -> Any:
    if op == "present":
        return rhs if rhs is not True else "x"

new_code:
_value_satisfying(op: str, rhs: Any, field_type: type) -> Any:
    if op == "present":
        if field_type == int:
            return 0
        elif field_type == bool:
            return True
        elif field_type == str:
            return "x"
        elif field_type == list:
            return []
